import{_ as t,o as l,c as a,a4 as i}from"./chunks/framework.2-Vke5-n.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"ソフトスキルガイドライン","tagline":"Soft Skills Guidelines","actions":[{"theme":"brand","text":"ソフトスキルガイドライン","link":"./softskill_guidelines.md"}]}},"headers":[],"relativePath":"documents/forSoftSkill/index.md","filePath":"documents/forSoftSkill/index.md"}'),o={name:"documents/forSoftSkill/index.md"};function s(n,e,r,d,c,p){return l(),a("div",null,[...e[0]||(e[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>現代のソフトウェアアーキテクトの役割は、技術的に正しく設計するだけにとどまらない。ビジネスと技術、多様な利害関係者を繋ぎ、プロジェクトの成功に向けて主体的・能動的に推進することが求められる。フューチャーにおいてもアーキテクトは、純粋な実装力や最新技術トレンドへの追随といったハードスキルだけでなく、プロジェクト経験などに裏打ちされた豊富な知見に加え、立ち振舞いなどのソフトスキル（コンサルスキル、ビジネススキル）が重視されている。</p><p>本ガイドラインは、この<strong>非技術的な領域</strong>に焦点を当て、アーキテクトがプロジェクトを成功に導き、提供価値を最大化するために不可欠なソフトスキルを体系化し定義することを目的とする。</p><p>対象者は、アーキテクトを目指すミドルクラスのコンサルタントを想定している。技術特化型のスペシャリストキャリアについてはここでは想定せず、技術力をビジネス視点やソフトスキルを利用してレバレッジを効かせることができる、ジェネラリスト型のアーキテクトに求められるソフトスキルへ焦点を当てている。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>本ドキュメントは実験的な位置づけであり、現時点では社内にて教育・採用・評価などで運用されていない</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、永井優斗</li><li><strong>レビュアー</strong>: 武田大輝、佐藤一馬、澁川喜規、赤坂優太、井上拓、清水利博</li></ul><div class="next-page-nav"><p>次のページ: <a href="./softskill_guidelines.html">ソフトスキルガイドライン</a></p></div>',9)])])}const m=t(o,[["render",s]]);export{_ as __pageData,m as default};
